// Paste the channel_secret you sent to RailWatch when you created the watch.
const SECRET = 'replace-with-your-channel-secret';
const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const given = String(headers['x-railwatch-signature'] || '').trim();
// Raw Body is on in the Webhook node, so the exact bytes RailWatch signed are in binary.data.
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(given);
const valid = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!valid) {
  return [{ json: { valid: false } }];
}
const env = JSON.parse(raw.toString('utf8'));
const lines = [`**${env.watch_name || 'RailWatch'}**: ${env.event_count || 0} change(s)`];
for (const ev of (env.events || []).slice(0, 10)) {
  const title = ev.title || ev.identity || 'change';
  const head = ev.url ? `[${title}](<${ev.url}>)` : title;
  lines.push(`- \`${ev.change_type || 'change'}\` ${head}: ${ev.summary || ''}`);
}
return [{ json: { valid: true, deliveryId: env.delivery_id || null, envelope: env, discord: { content: lines.join('\n').slice(0, 1990), allowed_mentions: { parse: [] } } } }];
